void init_array(
    int n,
    int m,
    double *alpha,
    double *beta,
    double C[30][30],
    double A[30][20]) {
    int i, j;

    *alpha = 1.5;
    *beta = 1.2;
    for (i = 0; i < n; i++)
        for (j = 0; j < m; j++)
            A[i][j] = (double)((i * j + 1) % n) / n;
    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++)
            C[i][j] = (double)((i * j + 2) % m) / m;
}

